<?php
require __DIR__ . '/config.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
$stmt = db()->prepare("SELECT * FROM games WHERE id=?"); $stmt->execute([$id]); $game = $stmt->fetch();
if (!$game) { http_response_code(404); exit('Game not found.'); }
db()->prepare("UPDATE games SET views=views+1 WHERE id=?")->execute([$id]);
$ss = db()->prepare("SELECT * FROM game_screenshots WHERE game_id=? ORDER BY sort_order,id"); $ss->execute([$id]); $screenshots=$ss->fetchAll();
$src = db()->prepare("SELECT * FROM game_sources WHERE game_id=? ORDER BY sort_order,id"); $src->execute([$id]); $sources=$src->fetchAll();
$req = db()->prepare("SELECT * FROM game_requirements WHERE game_id=?"); $req->execute([$id]); $requirements=[]; foreach($req as $r) $requirements[$r['kind']]=$r;
$related = db()->prepare("SELECT id,title,cover_url,genre FROM games WHERE id<>? AND (genre=? OR developer=?) ORDER BY featured DESC LIMIT 4"); $related->execute([$id,$game['genre'],$game['developer']]); $related=$related->fetchAll();
$video = youtube_embed($game['trailer_url'] ?? '');
?>
