<section class="panel"><div class="section-head"><h2>SYSTEM REQUIREMENTS</h2><span class="eyebrow">03 / HARDWARE</span></div><div class="requirements"><?php foreach(['minimum'=>'MINIMUM','recommended'=>'RECOMMENDED'] as $key=>$label): $r=$requirements[$key]??[]; ?><div class="req-card"><h3><?= $label ?></h3><?php foreach(['os'=>'Operating system','processor'=>'Processor','memory'=>'Memory','graphics'=>'Graphics','directx'=>'DirectX','storage'=>'Storage'] as $field=>$name): ?><div class="req-row"><span><?= $name ?></span><b><?=e($r[$field]??'Not specified')?></b></div><?php endforeach; ?></div><?php endforeach; ?></div><p class="small muted">Check the publisher's current specifications before purchasing or installing.</p></section>
